      consumer->position += s;
      uint8_t c;
      if (!pni_consumer_readf8(subconsumer, &c)) return false;
      *count = c;
      return pni_consumer_readf8(subconsumer, element_type);
    }
    default:
      pni_consumer_skip_value(consumer, type);
      return false;
  }
